      { q: "In che senso Morante rinnova l'epica?", options: ["Elimina ogni evento collettivo", "Attribuisce grandezza narrativa a figure normalmente marginali", "Ripropone senza cambiamenti gli eroi antichi"], correct: 1, explanation: "Bambini, donne e animali diventano misure della storia comune.", anchor: "conclusione-eredita", recovery: ["Eroi senza potere", "L'epica moderna può raccontare chi subisce gli eventi, non soltanto chi li guida.", "Useppe acquista rilievo universale pur non controllando nulla della guerra."] },
      { q: "Quale rischio contiene l'antitesi Felici Pochi/Infelici Molti?", options: ["Cancellare ogni distinzione morale", "Ridurre l'importanza dell'infanzia", "Irrigidirsi in una nuova gerarchia fra puri e compromessi"], correct: 2, explanation: "Una figura polemica diventa ingiusta se classifica una volta per tutte le persone.", anchor: "conclusione-limiti", recovery: ["L'antitesi sotto critica", "Anche una distinzione nata contro il Potere può diventare esclusiva.", "Chi oggi resiste può domani conformarsi, e viceversa."] },
      { q: "Come va affrontata la controversia sul sentimentalismo?", options: ["Negando che il romanzo orienti le emozioni", "Rifiutando ogni emozione come manipolazione", "Tenendo insieme il rischio di guidare la pietà e quello di svalutare la vulnerabilità"], correct: 2, explanation: "Il giudizio critico deve esaminare la tecnica emotiva senza disprezzare il dolore narrato.", anchor: "conclusione-limiti", recovery: ["Emozione e rigore", "Commuovere non è automaticamente manipolare; occorre vedere come il testo costruisce l'effetto.", "La morte di un bambino può essere narrata con forza e insieme richiedere analisi formale."] },
      { q: "Che uso contemporaneo possiamo fare della domanda morantiana?", options: ["Rifiutare qualunque istituzione", "Chiedere chi paga concretamente parole come progresso o sicurezza", "Sostituire la politica con la poesia"], correct: 1, explanation: "Morante offre un controllo morale delle astrazioni, non un programma amministrativo completo.", anchor: "conclusione-oggi", recovery: ["Dalle parole ai corpi", "Un concetto pubblico va tradotto nelle sue conseguenze visibili.", "Dire 'emergenza' non basta: bisogna osservare chi perde diritti o protezione."] },
      { q: "Quale domanda conclude il percorso?", options: ["Se si possa difendere l'innocenza senza ridurla all'impotenza", "Se ogni fantasia sia falsa", "Se la storia possa essere cancellata dai romanzi"], correct: 0, explanation: "La compassione deve misurarsi con il problema dell'azione e della responsabilità.", anchor: "conclusione-domanda", recovery: ["Innocenza e azione", "Proteggere chi è vulnerabile richiede anche decisioni e organizzazione.", "Una comunità deve limitare il potere senza rinunciare a intervenire contro la violenza."] }
